//! Directory resolution abstraction for platform-specific paths.
//!
//! This module provides a trait-based abstraction over directory resolution,
//! enabling dependency injection for testing. The [`BaseDirs`] trait defines
//! the interface for resolving platform-specific directories, while
//! [`SystemBaseDirs`] provides the real implementation using the
//! `directories-next` crate.
//!
//! # Testing
//!
//! In tests, use `MockBaseDirs` (generated by mockall) to avoid writing to
//! the user's actual home directory.

use std::path::PathBuf;

/// Returns the XDG bin home directory if set and absolute.
#[cfg(unix)]
fn xdg_bin_home() -> Option<PathBuf> {
    std::env::var_os("XDG_BIN_HOME")
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
}

/// Returns the data-directory override that debug builds honour.
///
/// Integration tests drive the real binary, which resolves its data directory
/// from a platform API that ignores `XDG_DATA_HOME` on Windows. The override
/// lets such a test keep the installation record inside its own temporary
/// directory. Release builds ignore it, so it cannot relocate a real install.
fn test_data_home() -> Option<PathBuf> {
    if !cfg!(debug_assertions) {
        return None;
    }
    std::env::var_os(crate::test_support::TEST_DATA_HOME_ENV)
        .map(PathBuf::from)
        .filter(|path| path.is_absolute())
}

/// Returns the executable-directory override that debug builds honour.
///
/// The bin root has the same portability problem as the data directory:
/// Windows derives it from the home directory in the profile known folder,
/// which ignores `HOME` and `XDG_BIN_HOME`. The override lets an integration
/// test point the binary at a directory it can inspect. Release builds ignore
/// it, so it cannot relocate a real installation.
fn test_executable_home() -> Option<PathBuf> {
    if !cfg!(debug_assertions) {
        return None;
    }
    std::env::var_os(crate::test_support::TEST_EXECUTABLE_HOME_ENV)
        .map(PathBuf::from)
        .filter(|path| path.is_absolute())
}

/// Abstraction for resolving platform-specific base directories.
///
/// This trait enables dependency injection for directory resolution,
/// allowing tests to use mock implementations that don't touch the
/// real filesystem.
///
/// # Examples
///
/// ```no_run
/// use whitaker_installer::dirs::{BaseDirs, SystemBaseDirs};
///
/// let dirs = SystemBaseDirs::new().expect("failed to initialize directories");
/// if let Some(bin_dir) = dirs.executables() {
///     println!("Executables go in: {}", bin_dir.display());
/// }
/// ```
#[cfg_attr(test, mockall::automock)]
pub trait BaseDirs {
    /// Returns the user's home directory.
    ///
    /// - Unix: `$HOME` or `/home/<user>`
    /// - Windows: `%USERPROFILE%` or `C:\Users\<user>`
    fn home(&self) -> Option<PathBuf>;

    /// Returns the directory for user executables.
    ///
    /// On Unix, respects `XDG_BIN_HOME` if set, otherwise falls back to
    /// `~/.local/bin`. On Windows, returns `~/.local/bin`. This follows the
    /// XDG Base Directory Specification convention. Debug builds of
    /// [`SystemBaseDirs`] honour
    /// [`crate::test_support::TEST_EXECUTABLE_HOME_ENV`] first, so an
    /// integration test can inspect the directory the binary actually used.
    fn executables(&self) -> Option<PathBuf>;

    /// Returns the directory for cloning the Whitaker repository.
    ///
    /// - Linux: `~/.local/share/whitaker`
    /// - macOS: `~/Library/Application Support/whitaker`
    /// - Windows: `%LOCALAPPDATA%\whitaker`
    fn whitaker_data(&self) -> Option<PathBuf>;

    /// Returns the directory holding the installed Dylint bootstrap.
    ///
    /// It sits beside [`Self::whitaker_data`], never inside it, because
    /// that directory is itself the managed Git clone. On Linux this is
    /// `$XDG_DATA_HOME/whitaker-bootstrap`, falling back to
    /// `~/.local/share/whitaker-bootstrap`.
    fn bootstrap_dir(&self) -> Option<PathBuf> {
        self.whitaker_data().and_then(|data_dir| {
            data_dir
                .parent()
                .map(|root| root.join("whitaker-bootstrap"))
        })
    }
}

/// Real implementation of [`BaseDirs`] using the `directories-next` crate.
///
/// This implementation resolves actual platform-specific directories
/// and should be used in production code. It wraps `directories_next::UserDirs`
/// and `directories_next::ProjectDirs` to provide consistent cross-platform
/// directory resolution.
///
/// Debug builds honour [`crate::test_support::TEST_DATA_HOME_ENV`] for
/// [`BaseDirs::whitaker_data`] and
/// [`crate::test_support::TEST_EXECUTABLE_HOME_ENV`] for
/// [`BaseDirs::executables`], so an integration test that drives the binary
/// can keep the installation record and the executable directory in its own
/// temporary tree on platforms whose directories come from APIs that ignore
/// `XDG_DATA_HOME` and `XDG_BIN_HOME`. Release builds ignore both variables.
///
/// # Examples
///
/// ```no_run
/// use whitaker_installer::dirs::{BaseDirs, SystemBaseDirs};
///
/// let dirs = SystemBaseDirs::new().expect("failed to initialize directories");
/// let data_dir = dirs
///     .whitaker_data()
///     .expect("could not determine data directory");
/// println!("Whitaker data at: {}", data_dir.display());
/// ```
#[derive(Debug, Clone)]
pub struct SystemBaseDirs {
    user_dirs: directories_next::UserDirs,
    project_dirs: directories_next::ProjectDirs,
}

impl SystemBaseDirs {
    /// Creates a new `SystemBaseDirs` instance.
    ///
    /// Returns `None` if the platform's directory conventions cannot be
    /// determined (e.g., on unsupported platforms or when environment
    /// variables are not set correctly).
    #[must_use]
    pub fn new() -> Option<Self> {
        let user_dirs = directories_next::UserDirs::new()?;
        let project_dirs = directories_next::ProjectDirs::from("io", "github", "whitaker")?;
        Some(Self {
            user_dirs,
            project_dirs,
        })
    }
}

impl BaseDirs for SystemBaseDirs {
    fn home(&self) -> Option<PathBuf> { Some(self.user_dirs.home_dir().to_owned()) }

    fn executables(&self) -> Option<PathBuf> {
        if let Some(path) = test_executable_home() {
            return Some(path);
        }
        #[cfg(unix)]
        if let Some(path) = xdg_bin_home() {
            return Some(path);
        }
        self.home().map(|h| h.join(".local").join("bin"))
    }

    fn whitaker_data(&self) -> Option<PathBuf> {
        test_data_home().or_else(|| Some(self.project_dirs.data_dir().to_owned()))
    }
}

#[cfg(test)]
mod tests {
    //! Tests for base-directory resolution.

    use super::*;
    use crate::test_support::env_test_guard;

    #[test]
    fn system_base_dirs_returns_some_on_supported_platforms() {
        let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");

        assert!(dirs.home().is_some(), "expected home_dir to return Some");
    }

    #[test]
    fn whitaker_data_dir_contains_whitaker() {
        let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
        let data_dir = dirs.whitaker_data();

        assert!(
            data_dir.is_some(),
            "expected whitaker_data_dir to return Some"
        );
        assert!(
            data_dir
                .as_ref()
                .is_some_and(|p| p.to_string_lossy().contains("whitaker")),
            "expected path to contain 'whitaker'"
        );
    }

    #[test]
    fn bootstrap_dir_sits_beside_the_managed_clone() {
        let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
        let data_dir = dirs.whitaker_data().expect("data dir");
        let bootstrap = dirs.bootstrap_dir().expect("bootstrap dir");

        assert_eq!(bootstrap.parent(), data_dir.parent());
        assert!(
            !bootstrap.starts_with(&data_dir),
            "never inside the Git clone"
        );
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn bootstrap_dir_honours_xdg_data_home() {
        let _guard = env_test_guard();
        temp_env::with_var("XDG_DATA_HOME", Some("/custom/share"), || {
            let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");

            assert_eq!(
                dirs.bootstrap_dir(),
                Some(PathBuf::from("/custom/share/whitaker-bootstrap"))
            );
        });
    }

    #[cfg(debug_assertions)]
    #[test]
    fn debug_builds_honour_the_data_home_override() {
        let _guard = env_test_guard();
        let override_root = std::env::temp_dir().join("whitaker-test-data-home");
        let expected = override_root.clone();

        temp_env::with_var(
            crate::test_support::TEST_DATA_HOME_ENV,
            Some(&override_root),
            || {
                let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");

                assert_eq!(dirs.whitaker_data(), Some(expected));
            },
        );
    }

    #[cfg(debug_assertions)]
    #[test]
    fn a_relative_data_home_override_is_ignored() {
        let _guard = env_test_guard();

        temp_env::with_var(
            crate::test_support::TEST_DATA_HOME_ENV,
            Some("relative/data"),
            || {
                let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
                let data_dir = dirs.whitaker_data().expect("data dir");

                assert!(
                    data_dir.is_absolute(),
                    "a relative override must not replace the platform data directory"
                );
            },
        );
    }

    #[cfg(debug_assertions)]
    #[test]
    fn debug_builds_honour_the_executable_home_override() {
        let _guard = env_test_guard();
        let override_root = std::env::temp_dir().join("whitaker-test-executable-home");
        let expected = override_root.clone();

        temp_env::with_var(
            crate::test_support::TEST_EXECUTABLE_HOME_ENV,
            Some(&override_root),
            || {
                let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");

                assert_eq!(dirs.executables(), Some(expected));
            },
        );
    }

    #[cfg(debug_assertions)]
    #[test]
    fn a_relative_executable_home_override_is_ignored() {
        let _guard = env_test_guard();

        temp_env::with_var(
            crate::test_support::TEST_EXECUTABLE_HOME_ENV,
            Some("relative/bin"),
            || {
                let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
                let bin_dir = dirs.executables().expect("bin dir");

                assert!(
                    bin_dir.is_absolute(),
                    "a relative override must not replace the platform executable directory"
                );
            },
        );
    }

    #[test]
    fn bin_dir_defaults_to_local_bin() {
        let _guard = env_test_guard();
        // Temporarily unset XDG_BIN_HOME to test the fallback
        temp_env::with_var_unset("XDG_BIN_HOME", || {
            let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
            let bin_dir = dirs.executables();

            assert!(bin_dir.is_some(), "expected bin_dir to return Some");
            assert!(
                bin_dir
                    .as_ref()
                    .is_some_and(|p| p.to_string_lossy().contains(".local")),
                "expected path to contain '.local'"
            );
        });
    }

    #[cfg(unix)]
    #[test]
    fn bin_dir_respects_xdg_bin_home() {
        let _guard = env_test_guard();
        temp_env::with_var("XDG_BIN_HOME", Some("/custom/bin"), || {
            let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
            let bin_dir = dirs.executables().expect("expected bin_dir to return Some");

            assert_eq!(bin_dir, PathBuf::from("/custom/bin"));
        });
    }

    #[cfg(unix)]
    #[test]
    fn bin_dir_ignores_relative_xdg_bin_home() {
        let _guard = env_test_guard();
        temp_env::with_var("XDG_BIN_HOME", Some("relative/path"), || {
            let dirs = SystemBaseDirs::new().expect("failed to create SystemBaseDirs");
            let bin_dir = dirs.executables().expect("expected bin_dir to return Some");

            // Should fall back to ~/.local/bin since XDG_BIN_HOME is relative
            assert!(
                bin_dir.to_string_lossy().contains(".local"),
                "expected path to contain '.local' when XDG_BIN_HOME is relative"
            );
        });
    }
}
